/** Keyboard shortcuts, shown in the Guide. Each works only on the pages named here; the sidebar footer lists
 * the ones that work on the page you are on. */
export const SHORTCUTS: { keys: string; action: string; where: string }[] = [
  { keys: "Ctrl+S (Cmd+S on Mac)", action: "Save", where: "New quote, invoice drafts, client details, Shop items (item editor), Settings, Filament materials, Electricity, Printers" },
  { keys: "Ctrl+K (Cmd+K on Mac)", action: "Jump to the page's filter box", where: "Quotes, Invoices, Clients, Requests, Shop items, Filament spools, Recent prints on New quote" },
  { keys: "Esc", action: "Close the open menu or the sidebar drawer", where: "Everywhere" },
];

/** Every image key the task topics reference, in reading order. scripts/guide-shots.ts captures exactly these. */
export const GUIDE_IMAGE_KEYS: string[] = GUIDE_TASKS.flatMap((t) => t.steps.flatMap((s) => (s.image ? [s.image.key] : [])));

/** The topic list in the order the Guide shows it: tasks first, then concepts, then the shortcuts reference. */
export const GUIDE_NAV: { group: string; items: { id: string; title: string }[] }[] = [
  { group: "Tasks", items: GUIDE_TASKS.map((t) => ({ id: t.id, title: t.title })) },
  { group: "Concepts", items: GUIDE_TOPICS.map((t) => ({ id: t.id, title: t.title })) },
  { group: "Reference", items: [{ id: "keyboard-shortcuts", title: "Keyboard shortcuts" }] },
];

/** The topic a `#/guide#<fragment>` address opens. An unknown or missing fragment opens the first task. */
export function resolveGuideTopic(fragment: string | null): string {
  const ids = GUIDE_NAV.flatMap((g) => g.items.map((i) => i.id));
  return fragment && ids.includes(fragment) ? fragment : GUIDE_TASKS[0]!.id;
}
